//copied from SRC Shell 27/10/26 - 3213 ESS 2027 //
//Changed skip code from 1000 to 99 for Qilt //

// set skip code to unanswered questions - questions must be non-mandatory
// default skip code set to 1000 - use List_Skip reusable list
// add this function to questions custom validation, or uncomment in global validation
// uncomment hideSkipCode() in 'Look & feel' in JavaScript section
function setSkipCode(code='99') {
    var q = f(CurrentForm());

    if (q.getType() == "3DGrid") { // multi grid
        var questionIds = Get3DGridQuestionIds(CurrentForm());

        var emptyRows = questionIds.filter(function (item) {
            return !f(item).toBoolean();
        });

        if (
            String(questionIds).split(",")[0].includes(`,${code},`) ||
            String(questionIds).split(",")[0].startsWith(`${code},`) ||
            String(questionIds).split(",")[0].endsWith(`,${code}`)
        ) {
            if (emptyRows.length > 0) {
                var cat = a(CurrentForm()).toString();

                if (
                    cat.includes(`,${code},`) ||
                    cat.startsWith(`${code},`) ||
                    cat.endsWith(`,${code}`)
                ) {
                    skipMessage();

                    emptyRows.forEach(function (item) {
                        if (f(item).item(code).DICHOTOMY) {
                            f(item).item(code).set('1');
                        }
                    });
                }
            }

            questionIds.forEach(function (item) {
                if (f(item).size() > 1) {
                    f(item).item(code).set('0');
                }
            });

        }
    } else if (q.COMPOUND) {
        var rows = q.domainValues();
        var firstRow = CurrentForm() + "_" + rows[0];

        if (f(firstRow).CODED) { // single grid
            var cat = a(firstRow).toString();

            if (
                cat.includes(`,${code},`) ||
                cat.startsWith(`${code},`) ||
                cat.endsWith(`,${code}`)
            ) {
                var emptyRows = rows.filter(function (item) {
                    return !f(CurrentForm() + "_" + item).toBoolean();
                });

                if (emptyRows.length > 0) {
                    skipMessage();

                    emptyRows.forEach(function (item) {
                        f(CurrentForm() + "_" + item).set(code);
                    });
                }
            }

        } else if (!q.toBoolean()) { // standard multi
            var cat = a(CurrentForm()).toString();

            if (
                cat.includes(`,${code},`) ||
                cat.startsWith(`${code},`) ||
                cat.endsWith(`,${code}`)
            ) {
                if (q.item(code).DICHOTOMY) {
                    skipMessage();
                    q.item(code).set('1');
                }
                if (q.size()>1) {
                    q.item(code).set('0');
                }
            }
        }

    } else if (!q.toBoolean()) { // standard single
        var cat = a(CurrentForm()).toString();

        if (
            cat.includes(`,${code},`) ||
            cat.startsWith(`${code},`) ||
            cat.endsWith(`,${code}`)
        ) {
            if (q.CODED) {
                skipMessage();
                q.set(code);
            }
        }
    }

    function skipMessage() {
        /*RaiseError();
        ClearQuestionErrorMessage();
        ClearErrorMessage();
        SetQuestionErrorMessage(
            LangIDs.en_au,
            "Please provide an answer if you can. If you prefer not to answer this question, click Next to continue."
        );*/
    }
}


// add to custom validation for all JavaScript DK/REF questions
function setDKREF() {
    const qnIndex = String(a('qn_dkref'))
        .split(',')
        .map(s => s.trim())
        .filter(s => s.length > 0)
        .map(Number)
        .filter(Number.isFinite);
    const qnIndexSort = [...qnIndex].sort((a, b) => a - b);

    // check if question already exists and clear data
    qnIndexSort.forEach(val => {
        if (f('qn_dkref_' + val + '_other').get() == getLoopKey()) {
            f('qn_dkref_' + val).set(null);
            f('qn_dkref_' + val + '_other').set(null);
        }
    });

    // set if question is dk/ref
    const getnrv = f(CurrentForm()).getNoResponseValue();
    if (getnrv != null) {
        for (let val of qnIndexSort) {
            if (!f('qn_dkref_' + val + '_other').toBoolean()) {
                f('qn_dkref_' + val).set(getnrv);
                f('qn_dkref_' + val + '_other').set(getLoopKey());
                break;
            }
        }
    }
}
// save single/multi codeframe OR grid question order to qn_order
function setOrder() {
    var cat = "Unable to capture the order for this question type";
    var q = f(CurrentForm());
    var qType = q.getType();

    if (["3DGrid", "OPEN"].indexOf(qType) < 0) {
        cat = q.domainValues().toLocaleString();
    }
    const qnIndex = String(a('qn_order'))
        .split(',')
        .map(s => s.trim())
        .filter(s => s.length > 0)
        .map(Number)
        .filter(Number.isFinite);

    const qnIndexSort = [...qnIndex].sort((a, b) => a - b);

    // check if question already exists and clear data
    qnIndexSort.forEach(val => {
        if (f('qn_order_' + val + '_other').get() == getLoopKey()) {
            f('qn_order_' + val).set(null);
            f('qn_order_' + val + '_other').set(null);
        }
    });

    // save current order
    for (let val of qnIndexSort) {
        if (!f('qn_order_' + val + '_other').toBoolean()) {
            f('qn_order_' + val).set(cat);
            f('qn_order_' + val + '_other').set(getLoopKey());
            break;
        }
    }
}
function getLoopKey() {
    try {
        return CurrentForm() + "." + f(CurrentLoops()).get();
    }
    catch (e) {
        return CurrentForm();
    }
}

