Grid.StartupScript:
const head = document.getElementsByClassName('cf-table-layout__row--head')[0];
const rhead = Array.from(document.getElementsByClassName('cf-table-layout__row-group-start'));

for (let i = 1; i < rhead.length; i++) {
    const clone = head.cloneNode(true);
    rhead[i].before(clone);
}

