function maskAIUSE2() {

    var s=set()


    if (f('AIUSE').any('1')) {
        s=s.union(set('1'))
    }

    if (f('AIUSE').any('2')) {
        s=s.union(set('2'))
    }

    s.add('3')
    s.add('98')
    s.add('99') //the hidden skip code
    return s;
}

