Open.ValidationCode:
var qid = 'employer';
var qid_code = 'employer_anzsic_code';
var qid_label = 'employer_anzsic_label';

if (f(qid).get() !== null && f(qid_label).get() !== null) {
    if (f(qid).get().toUpperCase() !== f('employer_label').get().toUpperCase()) {
        f(qid_label).set(null);
        f(qid_code).set(null);
        f('employer_label').set(null);
    }
}

var numberReturnfromEmployer 
