Open.StartupScript:
//Converting first letter to uppercase

var m= "^f('SUPTERM_txt').get()^"
m = m.charAt(0).toUpperCase() + m.slice(1);

document.querySelector('#SUPEMX_dk_text').innerText = m + ' does not have email/ Don’t want to provide'
//document.querySelector('#SUPEMX_dk_text').innerText = 'Supervisor does not have email/ Don’t want to provide'

Open.ValidationCode:
const MaxTryCount = 1
if (f("SUPEMX").toBoolean()) {
    if (!IsEmail(f("SUPEMX"))) {
        errormessage('3');
        //errormessage('20');
    }
    else {
        f('SUPEMX').set(f('SUPEMX').get().trim())
        f('EmailCollected').set(f('SUPEMX').get())
        //Request the tempory key
        var APIKey = "redacted"
        //Request the tempory key
        var requestString = "https://api.everest.validity.com/api/2.0/validation/addresses/";
        if (f('SUPEMX').toBoolean()) {
            requestString = requestString + f('SUPEMX').get()

            var response = Http.Get(requestString, "", { "X-API-Key": APIKey });
            var jsonObj = JSON.parse(response);
            var resultReturn = JSON.parse(JSON.stringify(jsonObj["results"]))
            var resultCategory = JSON.stringify(resultReturn["category"])
            f('EmailReturnValues_category').set(resultCategory.toLowerCase().replace(/""/g, ""))
            f('EmailReturnText').set(JSON.stringify(resultReturn))

            var returnvalueCat = f('EmailReturnValues_category').get()

            if (returnvalueCat.includes("email_domain_invalid")) {

                //errormessage('17')
                errormessage('20')
            }
            else if (returnvalueCat.includes("email_address_invalid")) {
                //errormessage('18')
                errormessage('20')
            }
            else if (returnvalueCat.includes("email_account_invalid")) {
                //errormessage('19')
                errormessage('20')
            }
            else if (returnvalueCat.includes("accept_all", "role_address", "disposable") && Number(f('EmailCount1') || 0) < MaxTryCount) {
                f('EmailCount1').set(Number(f('EmailCount1') || 0) + 1)
                errormessage('20')

            }

        }
    }
}
