Open.ValidationCode:
if (f('SUPPHX').toBoolean())
{
    var num = f("SUPPHX").get();
    var re = /0[23478]\d{8}/
    var re2 = /1300\d{6}/
    var re3 = /1800\d{6}/
    if(!re.test(num) && !re2.test(num) && !re3.test(num))
    {
        errormessage('28');
    }

}

