function getTwoDates() {
    const today = new Date();
    const weekday = today.getDay(); // 0 = Sunday, 1 = Monday, ..., 6 = Saturday

    // First date logic
    const firstDate = new Date(today);
    if (weekday === 1) { // Monday
        firstDate.setDate(today.getDate() + 2);
    } else {
        firstDate.setDate(today.getDate() + 4);
    }

    // Second date logic (always add 11 days)
    const secondDate = new Date(today);
    secondDate.setDate(today.getDate() + 11);

    // Format helper
    const formatDate = (date) => {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    };

    return {
        originalDate: formatDate(today),
        firstDate: formatDate(firstDate),
       Date: formatDate(secondDate)
    };
}

const { firstDate, secondDate, originalDate } = getTwoDates();



